function createCheckout(pricing) {                 // Context; pricing is the strategy
  return { total: (qty) => pricing(qty) };
}

const strategies = {                               // named strategy registry
  retail: (q) => q * 9.99,
  bulk:   (q) => (q > 100 ? q * 7.49 : q * 9.99),
};

const checkout = createCheckout(strategies.bulk);
